diff:
--- a/target/ast10x0/peripherals/smc/controller.rs
+++ b/target/ast10x0/peripherals/smc/controller.rs
@@ -397,6 +397,17 @@ impl<I: SmcInstance> Smc<I, Ready> {
         let baseline_ctrl = self.regs.read_cs_ctrl(cs);
         let geometry = S::resolve(&self.regs, cs, window_base, baseline_ctrl)?;

+        // Both `Discover` (SFDP) and `Pinned` (target-supplied const) can hand
+        // back a degenerate geometry -- SFDP via a corrupt/misparsed BFP table,
+        // `Pinned` via a copy-paste/typo'd constant. Downstream consumers (the
+        // flash backend's `size()`, `BlockingFlash::program`'s power-of-2
+        // assert on `program_window_size()`, `erasable_sizes_bitmap`'s
+        // `trailing_zeros()` shift, ...) all assume a validated, non-zero,
+        // power-of-two geometry, so enforce that once here instead of trusting
+        // every call site to re-check.
+        if geometry.capacity_bytes == 0
+            || !geometry.page_size.is_power_of_two()
+            || !geometry.sector_size.is_power_of_two()
+            || !geometry.block_size.is_power_of_two()
+        {
+            return Err(SmcError::InvalidCapacity);
+        }
+
         if geometry.capacity_bytes as usize > layout.region_size {
             return Err(SmcError::InvalidCapacity);
         }
--- a/target/ast10x0/backend/flash/src/lib.rs
+++ b/target/ast10x0/backend/flash/src/lib.rs
@@ -64,6 +64,8 @@ impl Blocking for NoWaitBlocking {
 pub struct Ast10x0FmcFlashDriver {
     fmc: FmcReady<FmcInstance>,
     geometry: FlashGeometry,
+    /// `geometry.capacity_bytes`, validated non-zero once in `new()`.
+    capacity: NonZero<usize>,
 }

 /// Stable alias used by the server binary for compile-time backend selection.
@@ -87,9 +89,9 @@ impl Ast10x0FmcFlashDriver {
             let cs1 = fmc.cs1().map_err(map_smc_error)?;
             cs1.geometry()
         };
-        NonZero::new(geometry.capacity_bytes as usize)
+        let capacity = NonZero::new(geometry.capacity_bytes as usize)
             .ok_or(error::FLASH_AST10X0_INVALID_CAPACITY)?;
-        Ok(Self { fmc, geometry })
+        Ok(Self { fmc, geometry, capacity })
     }

     fn device(&mut self) -> Result<SpiNorFlash<'_>, ErrorCode> {
@@ -105,7 +107,7 @@ impl FlashDriver for Ast10x0FmcFlashDriver {
     const PROGRAM_ALIGNMENT: usize = 1;

     fn size(&self) -> NonZero<usize> {
-        NonZero::new(self.geometry.capacity_bytes as usize).expect("capacity validated in new()")
+        self.capacity
     }

